import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const FEE_TYPES = ['심사', '재발급'];
const USE_YNS = ['사용', '미사용'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function invalid(message: string): ApiError {
  return new ApiError(422, 'FEE_UNIT_PRICE_INVALID', message);
}

function isBlank(v: unknown): boolean {
  return v === undefined || v === null || v === '';
}

function checkPrice(v: unknown): void {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  if (!Number.isFinite(n) || n < 0) {
    throw invalid('단가는 0 이상의 숫자로 입력해 주세요.');
  }
}

function checkDate(v: unknown, label: string): void {
  if (isBlank(v)) {
    return;
  }
  if (typeof v !== 'string' || !DATE_RE.test(v)) {
    throw invalid(label + '은(는) YYYY-MM-DD 형식으로 입력해 주세요.');
  }
}

function checkEnum(v: unknown, allowed: string[], label: string): void {
  if (typeof v !== 'string' || !allowed.includes(v)) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
}

function checkRange(from: unknown, to: unknown): void {
  if (!isBlank(from) && !isBlank(to) && String(to) < String(from)) {
    throw invalid('적용 종료일은 적용 시작일 이후여야 합니다.');
  }
}

function orNull(v: unknown): unknown {
  return isBlank(v) ? null : v;
}

@Controller('api/v1')
export class FnSfr04201Controller {
  @Get('/fee-unit-prices')
  async listFeeUnitPrices(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const page = isBlank(q['page']) ? 0 : Number(q['page']);
    const size = isBlank(q['size']) ? 20 : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const limit = Math.min(size, 200);
    const where: string[] = [];
    const params: Record<string, unknown> = {};
    if (!isBlank(q['feeType'])) {
      where.push('fee_type = :feeType');
      params['feeType'] = q['feeType'];
    }
    if (!isBlank(q['useYn'])) {
      where.push('use_yn = :useYn');
      params['useYn'] = q['useYn'];
    }
    if (!isBlank(q['effectiveDate'])) {
      if (typeof q['effectiveDate'] !== 'string' || !DATE_RE.test(q['effectiveDate'])) {
        throw new ApiError(400, 'VALIDATION_FAILED', '적용 기준일은 YYYY-MM-DD 형식으로 입력해 주세요.');
      }
      where.push('(effective_from IS NULL OR effective_from <= CAST(:effectiveDate AS date))');
      where.push('(effective_to IS NULL OR effective_to >= CAST(:effectiveDate AS date))');
      params['effectiveDate'] = q['effectiveDate'];
    }
    const cond = where.length > 0 ? ' WHERE ' + where.join(' AND ') : '';
    return transaction(async (db) => {
      const totalRows = await db.query('SELECT COUNT(*) AS total FROM fee_unit_price' + cond, params);
      const items = await db.query(
        'SELECT fee_unit_price_id AS "feeUnitPriceId", fee_type AS "feeType", unit_price AS "unitPrice", ' +
          'CAST(effective_from AS text) AS "effectiveFrom", CAST(effective_to AS text) AS "effectiveTo", ' +
          'use_yn AS "useYn" FROM fee_unit_price' + cond +
          ' ORDER BY fee_unit_price_id DESC LIMIT :limit OFFSET :offset',
        { ...params, limit, offset: page * limit },
      );
      return {
        items: items.map((r: any) => ({ ...r, unitPrice: Number(r.unitPrice) })),
        page,
        size: limit,
        total: Number(totalRows[0].total),
      };
    });
  }

  @Post('/fee-unit-prices')
  @HttpCode(200)
  async createFeeUnitPrice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    checkEnum(data['feeType'], FEE_TYPES, '수수료 구분');
    checkPrice(data['unitPrice']);
    checkEnum(data['useYn'], USE_YNS, '사용 여부');
    checkDate(data['effectiveFrom'], '적용 시작일');
    checkDate(data['effectiveTo'], '적용 종료일');
    checkRange(data['effectiveFrom'], data['effectiveTo']);
    return transaction(async (db) => {
      const rows = await db.query(
        'INSERT INTO fee_unit_price (fee_type, unit_price, effective_from, effective_to, use_yn, created_at, updated_at) ' +
          'VALUES (:feeType, CAST(:unitPrice AS numeric), CAST(:effectiveFrom AS date), CAST(:effectiveTo AS date), :useYn, now(), now()) ' +
          'RETURNING fee_unit_price_id AS "feeUnitPriceId"',
        {
          feeType: data['feeType'],
          unitPrice: String(data['unitPrice']),
          effectiveFrom: orNull(data['effectiveFrom']),
          effectiveTo: orNull(data['effectiveTo']),
          useYn: data['useYn'],
        },
      );
      return { feeUnitPriceId: Number(rows[0].feeUnitPriceId) };
    });
  }

  @Patch('/fee-unit-prices/:feeUnitPriceId')
  async updateFeeUnitPrice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = req.params['feeUnitPriceId'];
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    if (!/^\d+$/.test(id)) {
      throw new ApiError(404, 'FEE_UNIT_PRICE_NOT_FOUND', '수수료 단가를 찾을 수 없습니다.');
    }
    if (data['unitPrice'] !== undefined) {
      checkPrice(data['unitPrice']);
    }
    if (data['useYn'] !== undefined) {
      checkEnum(data['useYn'], USE_YNS, '사용 여부');
    }
    checkDate(data['effectiveFrom'], '적용 시작일');
    checkDate(data['effectiveTo'], '적용 종료일');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT CAST(effective_from AS text) AS "effectiveFrom", CAST(effective_to AS text) AS "effectiveTo" ' +
          'FROM fee_unit_price WHERE fee_unit_price_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'FEE_UNIT_PRICE_NOT_FOUND', '수수료 단가를 찾을 수 없습니다.');
      }
      const from = data['effectiveFrom'] !== undefined ? data['effectiveFrom'] : found[0].effectiveFrom;
      const to = data['effectiveTo'] !== undefined ? data['effectiveTo'] : found[0].effectiveTo;
      checkRange(from, to);
      const sets: string[] = [];
      const params: Record<string, unknown> = { id };
      if (data['unitPrice'] !== undefined) {
        sets.push('unit_price = CAST(:unitPrice AS numeric)');
        params['unitPrice'] = String(data['unitPrice']);
      }
      if (data['effectiveFrom'] !== undefined) {
        sets.push('effective_from = CAST(:effectiveFrom AS date)');
        params['effectiveFrom'] = orNull(data['effectiveFrom']);
      }
      if (data['effectiveTo'] !== undefined) {
        sets.push('effective_to = CAST(:effectiveTo AS date)');
        params['effectiveTo'] = orNull(data['effectiveTo']);
      }
      if (data['useYn'] !== undefined) {
        sets.push('use_yn = :useYn');
        params['useYn'] = data['useYn'];
      }
      sets.push('updated_at = now()');
      await db.execute(
        'UPDATE fee_unit_price SET ' + sets.join(', ') + ' WHERE fee_unit_price_id = CAST(:id AS bigint)',
        params,
      );
      return { feeUnitPriceId: Number(id) };
    });
  }

  @Delete('/fee-unit-prices/:feeUnitPriceId')
  async deleteFeeUnitPrice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '시스템 관리자');
    const id = req.params['feeUnitPriceId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(404, 'FEE_UNIT_PRICE_NOT_FOUND', '수수료 단가를 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const count = await db.execute(
        'DELETE FROM fee_unit_price WHERE fee_unit_price_id = CAST(:id AS bigint)',
        { id },
      );
      if (count === 0) {
        throw new ApiError(404, 'FEE_UNIT_PRICE_NOT_FOUND', '수수료 단가를 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

