import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field,
  NumberInput, DateInput, Select, ErrorText, Tiles,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const FEE_TYPES: [string, string][] = [['심사', '심사'], ['재발급', '재발급']];
const USE_YNS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const SIZE = 20;

type Mode =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

export default function FnSfr04201Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);
  const [form, setForm] = useState<Row>({});

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/fee-unit-prices', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  function openCreate() {
    setForm({ feeType: '', unitPrice: '', effectiveFrom: '', effectiveTo: '', useYn: '사용' });
    setMode({ kind: 'create' });
  }

  function openEdit(row: Row) {
    setForm({
      unitPrice: row.unitPrice,
      effectiveFrom: row.effectiveFrom ?? '',
      effectiveTo: row.effectiveTo ?? '',
      useYn: row.useYn,
    });
    setMode({ kind: 'edit', row });
  }

  function set(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  function done(message: string) {
    setMode(null);
    notify(message);
    reload();
  }

  async function create() {
    if (!form.feeType || form.unitPrice === '' || form.unitPrice === undefined || !form.useYn) {
      throw new Error('수수료 구분, 단가, 사용 여부를 입력해 주세요.');
    }
    await call('POST', '/fee-unit-prices', role, {
      feeType: form.feeType,
      unitPrice: form.unitPrice,
      effectiveFrom: form.effectiveFrom || undefined,
      effectiveTo: form.effectiveTo || undefined,
      useYn: form.useYn,
    });
    done('수수료 단가를 등록했습니다.');
  }

  async function update(row: Row) {
    if (form.unitPrice === '' || form.unitPrice === undefined) {
      throw new Error('단가를 입력해 주세요.');
    }
    await call('PATCH', '/fee-unit-prices/' + row.feeUnitPriceId, role, {
      unitPrice: form.unitPrice,
      effectiveFrom: form.effectiveFrom || undefined,
      effectiveTo: form.effectiveTo || undefined,
      useYn: form.useYn,
    });
    done('수수료 단가를 수정했습니다.');
  }

  async function remove(row: Row) {
    await call('DELETE', '/fee-unit-prices/' + row.feeUnitPriceId, role);
    done('수수료 단가를 삭제했습니다.');
  }

  function search() {
    setPage(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft({});
    setPage(0);
    setApplied({});
  }

  const columns = [
    { key: 'feeUnitPriceId', label: '수수료 단가 ID' },
    { key: 'feeType', label: '수수료 구분' },
    { key: 'unitPrice', label: '단가', render: (r: Row) => <Num value={r.unitPrice} /> },
    { key: 'effectiveFrom', label: '적용 시작일', render: (r: Row) => <DateText value={r.effectiveFrom} /> },
    { key: 'effectiveTo', label: '적용 종료일', render: (r: Row) => <DateText value={r.effectiveTo} /> },
    { key: 'useYn', label: '사용 여부', render: (r: Row) => <Badge value={r.useYn} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r: Row) => (
        <span>
          <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
          <button type="button" onClick={(e) => { e.stopPropagation(); setMode({ kind: 'delete', row: r }); }}>삭제</button>
        </span>
      ),
    },
  ];

  const items = data?.items ?? [];
  const inUse = items.filter((r) => r.useYn === '사용').length;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>단가 건수</h2>
        <Tiles items={[['전체 단가', <Num value={data?.total ?? 0} />], ['이 쪽의 사용 단가', <Num value={inUse} />]]} />
      </section>
      <section className="box span-12">
        <h2>수수료 단가</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="수수료 구분">
            <Select value={draft.feeType} onChange={(v) => setDraft({ ...draft, feeType: v })} options={FEE_TYPES} placeholder="전체" />
          </Field>
          <Field label="사용 여부">
            <Select value={draft.useYn} onChange={(v) => setDraft({ ...draft, useYn: v })} options={USE_YNS} placeholder="전체" />
          </Field>
          <Field label="적용 기준일">
            <DateInput value={draft.effectiveDate} onChange={(v) => setDraft({ ...draft, effectiveDate: v })} />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={openCreate}>단가 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable columns={columns} rows={items} onRowClick={(r) => openEdit(r)} empty="등록된 단가가 없습니다." />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>

      {mode && mode.kind === 'create' ? (
        <Drawer title="수수료 단가 등록" onClose={() => setMode(null)}>
          <Form onSubmit={create} submit="등록">
            <Field label="수수료 구분" required>
              <Select value={form.feeType} onChange={(v) => set('feeType', v)} options={FEE_TYPES} />
            </Field>
            <Field label="단가" required>
              <NumberInput value={form.unitPrice} onChange={(v) => set('unitPrice', v)} />
            </Field>
            <Field label="적용 시작일">
              <DateInput value={form.effectiveFrom} onChange={(v) => set('effectiveFrom', v)} />
            </Field>
            <Field label="적용 종료일">
              <DateInput value={form.effectiveTo} onChange={(v) => set('effectiveTo', v)} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={form.useYn} onChange={(v) => set('useYn', v)} options={USE_YNS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode && mode.kind === 'edit' ? (
        <Drawer title="수수료 단가 수정" onClose={() => setMode(null)}>
          <Pairs items={[['수수료 단가 ID', String(mode.row.feeUnitPriceId)], ['수수료 구분', String(mode.row.feeType)]]} />
          <Form onSubmit={() => update((mode as { kind: 'edit'; row: Row }).row)} submit="수정">
            <Field label="단가" required>
              <NumberInput value={form.unitPrice} onChange={(v) => set('unitPrice', v)} />
            </Field>
            <Field label="적용 시작일">
              <DateInput value={form.effectiveFrom} onChange={(v) => set('effectiveFrom', v)} />
            </Field>
            <Field label="적용 종료일">
              <DateInput value={form.effectiveTo} onChange={(v) => set('effectiveTo', v)} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={form.useYn} onChange={(v) => set('useYn', v)} options={USE_YNS} />
            </Field>
          </Form>
        </Drawer>
      ) : null}

      {mode && mode.kind === 'delete' ? (
        <Drawer title="수수료 단가 삭제" onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['수수료 단가 ID', String(mode.row.feeUnitPriceId)],
              ['수수료 구분', String(mode.row.feeType)],
              ['단가', <Num value={mode.row.unitPrice} />],
            ]}
          />
          <Form
            onSubmit={() => remove((mode as { kind: 'delete'; row: Row }).row)}
            submit="삭제"
            danger
            note="삭제한 단가는 되돌릴 수 없습니다."
          />
        </Drawer>
      ) : null}
    </div>
  );
}
